argv:
$ErrorActionPreference='Stop'
$root='E:\WebAIBridge-R66-R45-READONLY-TEST-20261014'
$head=([string](& git.exe -C $root rev-parse HEAD)).Trim()
if($head -ne 'c332d6eb5ac754deea43f169ebb191f087ced844'){throw 'ISOLATED_SHA_MISMATCH'}
$plan=Join-Path $root 'app\autonomy-r45-plan.example.json'
$p=Get-Content -LiteralPath $plan -Raw|ConvertFrom-Json
if($p.allowDispatch -ne $false -or $p.brain.enabled -ne $false){throw 'EXAMPLE_PLAN_MUST_REMAIN_DISABLED'}
$stateFile=Join-Path $root 'R45_OBSERVE_ONLY_20261014.json'
if(Test-Path -LiteralPath $stateFile){throw 'STATE_FILE_ALREADY_EXISTS'}
$raw=(& node.exe (Join-Path $root 'app\autonomy-r45-runner.js') --plan $plan --state $stateFile --bridge 'http://127.0.0.1:17448' --once 2>&1)
$exit=$LASTEXITCODE
if($exit -ne 0){Write-Output ('R45_OBSERVE_NODE_EXIT='+$exit);Write-Output (($raw|Out-String).Substring(0,[Math]::Min(1200,($raw|Out-String).Length)));throw 'OBSERVATION_FAILED'}
$j=($raw|Out-String|ConvertFrom-Json)
Write-Output ('RUN_STATUS='+$j.status)
Write-Output ('DISPATCHED_COUNT='+@($j.dispatched).Count)
Write-Output ('STATE_FILE_WRITTEN='+(Test-Path -LiteralPath $stateFile))
Write-Output ('PRODUCTION_HEAD='+(& git.exe -C 'E:\WebAIBridge' rev-parse HEAD))
if(@($j.dispatched).Count -ne 0){throw 'UNEXPECTED_DISPATCH'}
if($j.status -ne 'READ_ONLY'){throw ('OBSERVE_STATUS_NOT_READONLY '+$j.status)}
Write-Output 'READONLY_LIVE_BRIDGE_SMOKE_PASS=True'
